WITH RECURSIVE anc(jurisdiction_id, name, code, parent_id, level, root_code) AS (
  SELECT j.jurisdiction_id, j.name, j.code, j.parent_id, j.level, j.code FROM billing.tax_jurisdictions j WHERE j.level='city'
  UNION ALL
  SELECT a.jurisdiction_id, a.name, a.code, p.parent_id, p.level, p.code FROM anc a JOIN billing.tax_jurisdictions p ON p.jurisdiction_id = a.parent_id
)
SELECT jurisdiction_id, name, root_code AS country_code FROM anc WHERE level='region' ORDER BY jurisdiction_id;
